mapper.select:
SELECT table_schema, table_name, column_name, column_type, data_type, ( CASE WHEN ( is_nullable = 'no' && column_key != 'PRI' ) THEN '1' ELSE '0' END ) AS null_flag, ( CASE WHEN column_key = 'PRI' THEN '1' ELSE '0' END ) AS pk_flag, ( CASE WHEN extra = 'auto_increment' THEN '1' ELSE '0' END ) AS incr_flag, ordinal_position AS sort_flag, column_comment FROM information_schema.COLUMNS WHERE table_schema = (#{tableSchema}) AND table_name IN
#{name}
ORDER BY ordinal_position
